pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _test(uint256 _val, uint256 _val2) internal {
        vm.assume(_val != 0 && _val2 != 0);
        try c.SetMinSum(_val) {} catch { return; }
        try c.SetMinSum(_val2) {} catch { return; }
        assertTrue(c.MinSum() == _val2);
    }

    function testFuzz_test(uint256 _val, uint256 _val2) public {
        _test(_val, _val2);
    }

    receive() external payable {}
}
